// 🔑 KONFIGURASI TRIPAY — ganti dengan data dari dashboard Tripay lo
// (https://tripay.co.id -> Settings -> Merchat / Channel)
const TRIPAY_MERCHANT_CODE = 'T1234';      // Merchant Code lo
const TRIPAY_PRIVATE_KEY = 'PRIVATE-KEY-LO-DISINI';   // Private Key
const TRIPAY_API_KEY = 'API-KEY-LO-DISINI';           // API Key

// URL callback (harus HTTPS & bisa diakses publik)
// Ganti ke domain n8n lo yang sudah di-proxy Caddy
const CALLBACK_URL = 'https://N8N_DOMAIN_LO_DISINI/webhook/tripay-callback';

// URL return (ke halaman status di Vercel)
const RETURN_URL = 'https://VERCEL_DOMAIN_LO_DISINI/success.html';
const PENDING_URL = 'https://VERCEL_DOMAIN_LO_DISINI/pending.html';
const FAILED_URL = 'https://VERCEL_DOMAIN_LO_DISINI/failed.html';

// 🔧 JAM OPERASIONAL / PRODUKSI
// Sandbox:  https://tripay.co.id/api-sandbox/transaction/create
// Produksi: https://tripay.co.id/api/transaction/create
const TRIPAY_ENDPOINT = 'https://tripay.co.id/api/transaction/create';
const IS_SANDBOX = false; // true = pakai sandbox, false = produksi

// Data dari checkout page
const body = $input.first().json.body || {};
const nama = (body.nama || '').toString().trim();
const email = (body.email || '').toString().trim().toLowerCase();
const wa = (body.wa || '').toString().trim();
const produk = (body.produk || 'workshop-closing-naik-ai').toString();
const harga = Number(body.harga) || 299000;

// Validasi minimal
if (!nama || !email || !wa) {
  throw new Error('Data tidak lengkap: nama, email, dan WA wajib diisi');
}

// Merchant ref unik (order ID lo)
const timestamp = Date.now();
const merchantRef = 'WSH-' + timestamp.toString().slice(-10);

// Signature Tripay: HMAC-SHA256(merchantCode + merchantRef + amount, privateKey)
const crypto = require('crypto');
const signature = crypto
  .createHmac('sha256', TRIPAY_PRIVATE_KEY)
  .update(TRIPAY_MERCHANT_CODE + merchantRef + harga)
  .digest('hex');

// Order items (wajib untuk Tripay)
const orderItems = [{
  sku: produk,
  name: 'Workshop Closing Naik dengan AI - Live Zoom 2 Jam',
  price: harga,
  quantity: 1
}];

// Payload ke Tripay
const payload = {
  method: 'QRIS',           // GANTI: QRIS / BCAVA / BNI_VA / BRIVA / GOPAY / OVO / DANA / SHOPEEPAY
  merchant_ref: merchantRef,
  amount: harga,
  customer_name: nama,
  customer_email: email,
  customer_phone: wa.replace(/[^0-9]/g, ''),
  order_items: orderItems,
  callback_url: CALLBACK_URL,
  return_url: RETURN_URL,
  expire_time: 120,         // menit expired
  signature: signature
};

return {
  json: {
    endpoint: TRIPAY_ENDPOINT,
    apiKey: TRIPAY_API_KEY,
    payload: payload,
    merchantRef: merchantRef
  }
};

// Response dari Tripay
const tripayResp = $input.first().json;

// Tripay sukses: { success: true, data: { reference, payment_url, ... } }
if (!tripayResp.success) {
  throw new Error('Tripay error: ' + JSON.stringify(tripayResp));
}

const data = tripayResp.data || {};
const paymentUrl = data.payment_url;
const reference = data.reference || '';
const merchantRef = data.merchant_ref || '';

if (!paymentUrl) {
  throw new Error('payment_url kosong: ' + JSON.stringify(tripayResp));
}

return {
  json: {
    payment_url: paymentUrl,
    reference: reference,
    merchant_ref: merchantRef,
    amount: data.amount || 0
  }
};
